# app.py
def normalize_name(value: str) -> str:
    import string
    chars = []
    for char in value:
        if char.isalnum():
            chars.append(char.lower())
        elif char.isspace():
            chars.append(' ')
    return "-".join(c.strip() for c in "".join(chars).split())

