def squash_label(value):
    # Replace punctuation with space, lowercase letters, keep digits
    processed = ""
    for c in value:
        if c in string.punctuation:
            processed += " "
        elif c.isalpha():
            processed += c.lower()
        else:
            processed += c

    # Trim and collapse whitespace into hyphens
    return "-".join(processed.split())
